optimization-iteration.patch:
diff --git a/scripts/bot-evaluation/host-evidence.ts b/scripts/bot-evaluation/host-evidence.ts
index afc381fa..6b2f27e9 100644
--- a/scripts/bot-evaluation/host-evidence.ts
+++ b/scripts/bot-evaluation/host-evidence.ts
@@ -19,7 +19,11 @@ export function record(value: unknown): RecordValue {
     typeof value === "boolean"
   )
     return value;
-  if (Array.isArray(value)) return { item: value.map(record) };
+  if (Array.isArray(value)) {
+    const items: RecordValue[] = new Array(value.length);
+    for (let i = 0; i < value.length; i++) items[i] = record(value[i]);
+    return { item: items };
+  }
   return Object.fromEntries(
     Object.entries(value as object).map(([k, v]) => [
       k.replace(/[A-Z]/g, (c) => "_" + c.toLowerCase()),
